"""Apply the user's original travel density and retain the existing program."""
def make_days(places, day):
    for p in places.values():
        p.update(status='候选',day=None,note='')
    for key,name,coords,url in [
        ('garnier','加尼叶歌剧院〔新增近邻建议〕',[2.33167,48.87194],'https://www.operadeparis.fr/visites/palais-garnier'),
        ('vivienne','薇薇安拱廊〔新增顺路建议〕',[2.3394,48.8665],'https://www.wikidata.org/wiki/Q1314020')]:
        places[key]=dict(id=key,name=name,coordinates=coords,coordinate_source='公开地图地点位置；非入口精确定位',source_url=url,status='候选',day=None,note='新增项供review；原稿项目优先。')
    days=[
      day(1,'北京 → 巴黎',[],[],[],'往返交通','飞行、入境、入住；到达较早时可在住宿附近散步','这一天从北京前往巴黎，完成入境和入住。根据实际落地时间决定是否在酒店附近走走。','15天包含北京往返；先按本日抵达巴黎计算。'),
      day(2,'西岱岛与拉丁区',['notredame','sainte','conciergerie','cluny','curie','pantheon'],['flore'],[],'历史／中世纪艺术／科学史','按原稿参观时长合计约6–7小时；加午餐、排队和步行，全天约9–10小时','第一天我们将从西岱岛开始，再前往拉丁区。巴黎圣母院、圣礼拜堂和古监狱之后，继续参观中世纪博物馆、居里博物馆和先贤祠，恢复原文完整的一天。','居里只在周三至周六下午常规开放；实际顺序以这一条件和先贤祠最后入场倒推。花神是餐饮候选，不额外计算成参观任务。',[0,1,6]),
      day(3,'卢浮宫三翼',['louvre'],['royal'],[],'艺术','恢复三翼约8–8.5小时的原稿参观预算，另留午餐和休息；优先排夜场日','这一天主要游览卢浮宫，继续使用德农、叙利和黎塞留三翼的原稿路线。我们保留原来的深度参观目标，利用夜场安排足够的参观窗口。','完整三翼优先周三或周五夜场；皇家宫殿也安排在Day13，可在那天完成，无需从卢浮宫提前离开。',[1]),
      day(4,'玛黑区与现代巴黎的诞生',['bastille','vosges','carnavalet','picasso','hunt','arts'],['pinault'],[],'历史／艺术／科学技术','按原稿馆内约5.5–6.5小时；加午餐、步行和入场，约8–10小时','我们沿原稿从巴士底广场、孚日广场进入玛黑区，依次保留卡纳瓦莱、毕加索、狩猎自然和工艺博物馆。原来的景点内容继续保留，只核对各段移动及闭馆时刻。','皮诺保留：若夜场衔接合适，可接在本日；Day13也为它安排了确定位置，两处只去一次。毕加索沿用原稿“可选”身份，先纳入路线核对，不预先删去。',[0]),
      day(5,'橘园到凯旋门的巴黎西部轴线',['orangerie','decorative','marinehotel','concorde','petitpalais','grandpalais','champs','arc'],[],[],'艺术／建筑／城市史','沿用原稿各馆时长，馆内与登顶约7–8小时；加午餐、转场约10–12小时','这一天恢复原稿的橘园、装饰艺术、海军府、协和广场、小皇宫、大皇宫、香榭丽舍和凯旋门。大皇宫先按原稿外观参观，凯旋门放在晚间。','橘园较早开放、装饰艺术较晚开放，保留原稿先橘园后装饰艺术的安排；两者之间约1公里的回走可接受。若想看大皇宫展览，可与Day13中心区行程协调，不先取消其他馆。',[0,1]),
      day(6,'现代艺术、时装与塞纳河',['modern','tokyo','dior','trocadero','cruise'],[],[],'现代艺术／时装／城市景观','三个馆约4.5–5.5小时；观景、游船与午餐转场计入后，约8–10小时','这一天我们保留巴黎现代艺术博物馆、东京宫和迪奥艺廊，再前往夏乐宫观景平台，晚间坐塞纳河游船。原稿中的夏乐宫其他博物馆也保留，集中放在Day12。','东京宫从中午开放，不能与现代艺术馆同时安排上午入场。游船先保留原计划，具体是普通观光还是晚餐航程、哪个码头，下一阶段核实。',[0,1]),
      day(7,'奥赛、荣军院、罗丹与铁塔',['orsay','rodin','invalides','eiffel'],[],[],'艺术／军事历史／城市地标','奥赛约2–2.5小时、罗丹1–1.5小时、荣军院约3小时、铁塔2–3小时；连同午餐转场约11–13小时','这一天恢复原稿左岸与铁塔的主要项目。我们从奥赛开始，先在白天参观罗丹及花园，再前往相邻的荣军院，晚间登铁塔。下水道博物馆仍保留，放在同一区域的Day12。','这是原稿强度的一天。罗丹提前是为花园的冬季开放窗口；荣军院中的浮雕模型、解放勋章按原稿作为内部参观项目。最终核对铁塔预约后再锁定先后，不先删馆。',[0]),
      day(8,'凡尔赛完整庄园',['versailles','grandtrianon','petittrianon'],['venise'],[],'宫廷历史／建筑','主宫和大小特里亚农均保留；含酒店往返约10–12小时的规划预算','这一天按照旧地图，参观凡尔赛主宫、大特里亚农宫和小特里亚农宫。午餐与园区移动一起安排，继续保留完整庄园的目标。','冬季各宫殿开放与园区入口需要逐项核实；园内小火车或其他交通可用于转场，不以默认放弃某一宫殿来处理距离。',[0]),
      day(9,'蒙马特艺术区与巴黎北部',['sacre','tertre','romantic','moulin'],['datadog'],[],'艺术史／街区／个人到访','圣心堂、街区、浪漫生活馆与红磨坊外观约5–6小时；含午餐转场约7–8小时','我们恢复蒙马特的圣心堂、艺术家广场、浪漫生活博物馆和红磨坊。按街区路线衔接，不再把下午预先留空；Datadog沿用旧地图中的待确认到访点。','红磨坊目前按原稿外观，不自动购买演出票。浪漫生活馆具体开放、Datadog访问目的与停留时间待核对；北部区域与歌剧院可按实际预约串联，不强制替换。'),
      day(10,'拉维莱特科学与音乐',['science','philharmonie'],[],[],'科学／工业／音乐','科学城按原稿约2.5–4小时，另安排天文馆或馆内项目；爱乐厅／音乐博物馆约1.5–2小时，全天约7–9小时','这一天恢复科学与工业城和巴黎爱乐厅。科学城展览、天文馆等馆内项目按兴趣衔接，之后沿拉维莱特园区前往爱乐厅区域，保留科学与音乐的完整主题日。','天文馆、音乐博物馆、演出分别核实，当前不假定有某场音乐会。两处均来自旧地图，科学城不在另一个科学日重复安排。',[0]),
      day(11,'自然历史与巴黎地下空间',['natural','plants','post','catacombs'],['observatory'],[],'自然科学／通信技术／城市地下史','进化大展馆约2–2.5小时、植物园45分钟、邮政馆1–1.5小时、地下墓穴1–1.5小时；加午餐转场约8–10小时','这一天恢复原稿的自然历史、植物园、地下墓穴和邮政博物馆。先参观植物园区域，再用公共交通前往蒙帕纳斯和丹费尔一带，地下墓穴按预约安排在较晚时段。','天文台暂按附近外观点标注；入内须有可预约活动或访问安排。旧图中没有指定自然历史的具体展馆，这里明确为进化大展馆；工程关闭的古生物馆不当作已开放。',[0,1]),
      day(12,'夏乐宫博物馆与塞纳河工程',['sewer','maritime','homme','architecture','liberty'],['aquarium'],[],'工程／航海／人类学／建筑','下水道约1小时，夏乐宫三馆按原稿各约1–1.5小时，河岸与自由女神约45分钟；全天约8–10小时','我们从阿尔玛桥旁的下水道博物馆开始，跨河前往夏乐宫，保留国家海军、人类、建筑与遗产三馆，之后沿河前往自由女神像。原稿里的水族馆仍标作低优先级可选，不预先代替其他馆。','三馆地理集中，可按展览开放调整顺序。人类馆、建筑馆本来为可选，这里先恢复到完整路线供review；是否深入参观由你的兴趣决定，不做强制二选一。',[0,1]),
      day(13,'皇家宫殿、皮诺与中心街区',['garnier','royal','pinault','vivienne'],[],[],'建筑／当代艺术／中心街区','歌剧院约1.5小时、皇家宫殿45–60分钟、皮诺1.5–2小时、拱廊与街区约1小时；全天约7–8小时','我们把皇家宫殿和皮诺保留在中心城区的完整一天，串联附近的加尼叶歌剧院与薇薇安拱廊。若皮诺已在Day4夜场完成，可把这里用于原稿中想延长的展览或前面未完成的项目。','皇家宫殿与皮诺来自原稿；歌剧院和拱廊明确是新增近邻建议，待你review。它们不是用来强制替换原稿项目；可依你的兴趣和具体展览安排微调。',[1]),
      day(14,'巴黎 → 北京',[],[],[],'往返交通','离境日，具体可用时间取决于航班','这一天离开巴黎。航班若较晚，可利用住宿附近的时间收尾购物或散步，机场交通按最终航班安排。','不把尚未确定的航班前半天当作固定可用的游览日。'),
      day(15,'抵达北京',[],[],[],'往返交通','抵达与休息','返回北京，结束本次旅程。','实际航班跨日情况确定后调整边界。')]
    # Preserve the existing machine-readable status so the map stays compatible.
    for d in days:
        for field,status in [('core','建议主线'),('optional','当日可选'),('alternative','附近备选')]:
            for key in d[field]:
                if places[key].get('day') is None or field=='core':
                    places[key].update(status=status,day=d['day'])
    for key,note in {
        'msm':'用户明确本次不去。','poulard':'随圣米歇尔山取消。',
        'flore':'原稿餐饮点；按当天路线选择，不是必须消费的预订。',
        'venise':'原凡尔赛午餐点，继续保留为餐饮候选。',
        'datadog':'原地图个人到访点；目的、访问许可及停留待确认。',
        'observatory':'保留附近外观位置；普通公众入内须有开放活动，不能默认常规开放。',
        'cruise':'原图点位与人类馆重合，仍不沿用错误坐标；游船本身已恢复Day6，码头待确认。',
        'aquarium':'沿用原文低优先级可选身份，可在夏乐宫区域按当天兴趣加入。',
        'homme':'原稿可选，先纳入Day12核对路线；不强制与建筑馆二选一。',
        'architecture':'原稿可选，先纳入Day12核对路线；不强制与人类馆二选一。',
        'picasso':'原稿可选，先恢复到Day4完整路线，不先行删去。'
    }.items(): places[key]['note']=note
    places['msm']['status']=places['poulard']['status']='本次取消'
    places['cruise']['coordinates']=None
    return days
